/bin/zsh -lc "cat > tb_check.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 1;
  reg write_en = 0;
  reg [7:0] write_addr = 0;
  reg [3:0] write_data = 0;
  reg read_en = 0;
  reg [7:0] read_addr = 0;
  wire [3:0] read_data;

  TopModule dut(
    .clk(clk), .rst_n(rst_n),
    .write_en(write_en), .write_addr(write_addr), .write_data(write_data),
    .read_en(read_en), .read_addr(read_addr), .read_data(read_data)
  );

  always #5 clk = ~clk;

  task do_read(input [7:0] addr, input [3:0] exp, input [255:0] label);
    begin
      @(negedge clk);
      read_en = 1;
      read_addr = addr;
      @(posedge clk);
      #1;
      if (read_data "'!== exp) begin
        $display("FAIL %0s addr=%0d got=%h exp=%h", label, addr, read_data, exp);
        $fatal;
      end
      read_en = 0;
    end
  endtask

  initial begin
    rst_n = 0;
    #1;
    do_read(8'"'d0, 4'h0, \"reset0\");
    do_read(8'd7, 4'h0, \"reset7\");

    @(negedge clk);
    rst_n = 1;
    write_en = 1;
    write_addr = 8'd3;
    write_data = 4'ha;
    @(posedge clk);
    #1;
    write_en = 0;
    do_read(8'd3, 4'ha, \"write3\");

    @(negedge clk);
    write_en = 1;
    write_addr = 8'd130; // should alias to location 2
    write_data = 4'h5;
    @(posedge clk);
    #1;
    write_en = 0;
    do_read(8'd2, 4'h5, \"alias2\");
    do_read(8'd130, 4'h5, \"alias130\");

    "'$display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -Wall -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

